-- The Purchasing area (ARCHITECTURE v0.15 §12.0, §12.2; docs/plan.md §1.63, stream P-1): the
-- Materials pack's tables (the master list, each vendor's names for an item, every matching
-- decision, price observations) and the shared alert table (§5.2). Ported from the M8 branches'
-- 0006 and 0007 (2026-11-04). New tables plus one unique key on doc_line (its id is already the
-- primary key), so the previous Worker keeps working. Generated by drizzle-kit from
-- packages/db/src/schema.ts and packs/materials/src/schema.ts; the expression index, grants,
-- row-level security and pack comments at the end are hand-written.
-- First: the key the pack's composite foreign keys to doc_line need.
ALTER TABLE "doc_line" ADD CONSTRAINT "doc_line_id_tenant_key" UNIQUE("id","tenant_id");--> statement-breakpoint
CREATE TABLE "alert" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"pack" text,
	"kind" text NOT NULL,
	"subject_type" text NOT NULL,
	"subject_id" uuid NOT NULL,
	"severity" text NOT NULL,
	"title" text NOT NULL,
	"body" text NOT NULL,
	"evidence" jsonb NOT NULL,
	"facts" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"dollar_impact" numeric(14, 4),
	"currency" text DEFAULT 'USD' NOT NULL,
	"dedupe_key" text,
	"status" text DEFAULT 'open' NOT NULL,
	"raised_by_run_id" uuid,
	"agent_version_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"resolved_at" timestamp with time zone,
	"resolved_by" uuid,
	CONSTRAINT "alert_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "alert_severity_check" CHECK ("alert"."severity" in ('info', 'warning', 'critical')),
	CONSTRAINT "alert_status_check" CHECK ("alert"."status" in ('open', 'accepted', 'dismissed')),
	CONSTRAINT "alert_evidence_check" CHECK (jsonb_typeof("alert"."evidence") = 'array' and jsonb_array_length("alert"."evidence") > 0)
);
--> statement-breakpoint
CREATE TABLE "catalog_item" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"category" text NOT NULL,
	"canonical_name" text NOT NULL,
	"attributes" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"standard_uom" text NOT NULL,
	"key_signature" text,
	"embedding" vector(1024),
	"created_by_agent_version_id" uuid,
	"created_by_user_id" uuid,
	"merged_into_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"ext" jsonb DEFAULT '{}'::jsonb NOT NULL,
	CONSTRAINT "catalog_item_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "catalog_item_category_check" CHECK ("catalog_item"."category" in ('sheet_goods', 'hardwood', 'mouldings', 'hardware', 'finishes', 'other')),
	CONSTRAINT "catalog_item_standard_uom_check" CHECK ("catalog_item"."standard_uom" in ('sheet', 'board_foot', 'linear_foot', 'each', 'gallon', 'quart')),
	CONSTRAINT "catalog_item_not_merged_into_self" CHECK ("catalog_item"."merged_into_id" is distinct from "catalog_item"."id"),
	CONSTRAINT "catalog_item_created_by_check" CHECK (num_nonnulls("catalog_item"."created_by_agent_version_id", "catalog_item"."created_by_user_id") <= 1)
);
--> statement-breakpoint
CREATE TABLE "item_alias" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"vendor_id" uuid NOT NULL,
	"vendor_sku" text,
	"description_hash" text,
	"normalized_description" text,
	"catalog_item_id" uuid NOT NULL,
	"source" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "item_alias_source_check" CHECK ("item_alias"."source" in ('auto', 'human')),
	CONSTRAINT "item_alias_key_check" CHECK ("item_alias"."vendor_sku" is not null or "item_alias"."description_hash" is not null),
	CONSTRAINT "item_alias_description_hash_check" CHECK ("item_alias"."description_hash" is null or "item_alias"."description_hash" ~ '^[0-9a-f]{64}$')
