CREATE TABLE "item_match" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"doc_line_id" uuid NOT NULL,
	"catalog_item_id" uuid,
	"decision" text NOT NULL,
	"confidence" numeric(4, 3) NOT NULL,
	"method" text NOT NULL,
	"hinge_attribute" text,
	"candidates" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"agent_version_id" uuid,
	"decided_by_user_id" uuid,
	"decided_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "item_match_decision_check" CHECK ("item_match"."decision" in ('matched', 'new_item', 'unsure')),
	CONSTRAINT "item_match_method_check" CHECK ("item_match"."method" in ('alias', 'rules', 'llm', 'human')),
	CONSTRAINT "item_match_item_check" CHECK ("item_match"."decision" = 'unsure' or "item_match"."catalog_item_id" is not null),
	CONSTRAINT "item_match_confidence_check" CHECK ("item_match"."confidence" between 0 and 1),
	CONSTRAINT "item_match_decided_by_check" CHECK (num_nonnulls("item_match"."agent_version_id", "item_match"."decided_by_user_id") = 1)
);
