-- ARCHITECTURE §12.2: one alias per (client, vendor, sku, description hash), either part absent.
-- An expression index, which Drizzle cannot express; lookups and upserts use the same expressions.
CREATE UNIQUE INDEX item_alias_key ON item_alias
  (tenant_id, vendor_id, coalesce(vendor_sku, ''), coalesce(description_hash, ''));
--> statement-breakpoint
-- No DELETE for the runtime on any of them: a merge marks the merged item and repoints its
-- aliases and prices; a wrong alias is corrected by an update.
GRANT SELECT, INSERT, UPDATE ON catalog_item, item_alias, price_observation TO cs_runtime;
--> statement-breakpoint
-- Matching decisions are a log: a person's decision is a new row after the agent's.
GRANT SELECT, INSERT ON item_match TO cs_runtime;
--> statement-breakpoint
-- Alerts are kept: a person accepts or dismisses one (an update of its status), nothing deletes it.
GRANT SELECT, INSERT, UPDATE ON alert TO cs_runtime;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['alert', 'catalog_item', 'item_alias', 'item_match', 'price_observation'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
  END LOOP;
  -- Which pack owns a table: the platform's migration test checks pack tables for RLS and leaves
  -- their columns to the pack's own test (docs/plan.md §1.12, §1.63). alert is the platform's.
  FOREACH t IN ARRAY ARRAY['catalog_item', 'item_alias', 'item_match', 'price_observation'] LOOP
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:materials');
  END LOOP;
END
$$;
